from fractions import Fraction
bags = {'X': (Fraction(1, 3), ['R', 'G', 'G']), 'Y': (Fraction(2, 3), ['R', 'R', 'G'])}
num = Fraction(0)
den = Fraction(0)
for name, (prior, balls) in bags.items():
    for ball in balls:
        p = prior * Fraction(1, len(balls))
        if ball == 'R':
            den += p
            if name == 'X':
                num += p
print(num / den)

