from fractions import Fraction
from itertools import product
coins = {'P': ['H', 'T'], 'Q': ['H', 'H']}
post = {}
for name, faces in coins.items():
    lik = sum(Fraction(1, 4) for f in product(range(2), repeat=2)
              if [faces[i] for i in f] == ['H', 'H'])
    post[name] = Fraction(1, 2) * lik
print(post['Q'] / sum(post.values()))

