from fractions import Fraction
bags = {'X': ['R', 'R', 'B', 'B', 'B'], 'Y': ['R', 'R', 'R', 'R', 'B']}
num = Fraction(0)
den = Fraction(0)
for name, balls in bags.items():
    for ball in balls:
        p = Fraction(1, 2) * Fraction(1, len(balls))
        if ball == 'R':
            den += p
            if name == 'X':
                num += p
print(num / den)
